package com.lingdong.learning.student.web;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import com.lingdong.learning.student.application.BatchClassConfigurationService;import com.lingdong.learning.auth.application.AuthenticatedUser;import com.lingdong.learning.auth.domain.AuthClientType;import java.util.List;
class BatchClassConfigurationControllerTest {
 @Test void requiresExistingPermissionAndPreservesLongIdentifiers()throws Exception{var service=mock(BatchClassConfigurationService.class);var actor=new AuthenticatedUser(1L,1L,"fixture","fixture",AuthClientType.MINIAPP,List.of());long id=2110374231123427328L;when(service.configure(actor,31,32,List.of(id),"reason")).thenReturn(List.of(id));var response=new BatchClassConfigurationController(service).configure(actor,new BatchClassConfigurationController.Request(31,32,List.of(id),"reason"));assertEquals(1,response.affectedCount());assertEquals(List.of(Long.toString(id)),response.studentIds());var method=BatchClassConfigurationController.class.getDeclaredMethod("configure",AuthenticatedUser.class,BatchClassConfigurationController.Request.class);assertEquals("STUDENT_ORGANIZATION_MANAGE",method.getAnnotation(com.lingdong.learning.common.security.RequirePermission.class).value());assertArrayEquals(new String[]{"/class-configurations:batch"},method.getAnnotation(org.springframework.web.bind.annotation.PostMapping.class).value());}
 @Test void invalidRequestsFailBeanValidation(){try(var factory=jakarta.validation.Validation.buildDefaultValidatorFactory()){var validator=factory.getValidator();assertFalse(validator.validate(new BatchClassConfigurationController.Request(0,0,List.of(),"")).isEmpty());assertFalse(validator.validate(new BatchClassConfigurationController.Request(31,32,java.util.Collections.nCopies(51,1L),"reason")).isEmpty());assertFalse(validator.validate(new BatchClassConfigurationController.Request(31,32,List.of(-1L),"reason")).isEmpty());}}
}
